#!/usr/bin/env python3
import csv
import json
from pathlib import Path
from typing import Any, Dict, Iterable, List

ROOT = Path('/root')
CATALOG_PATH = ROOT / 'therapy_catalog.json'
BAG_PATH = ROOT / 'bag_supply_cost.csv'
PAYMENT_PATH = ROOT / 'delivery_payment.csv'
OVERRIDES_PATH = ROOT / 'patient_overrides.csv'
OUTPUT_JSON_PATH = ROOT / 'infusion_batch_analysis.json'
OUTPUT_MD_PATH = ROOT / 'infusion_batch_summary.md'


def as_bool(value: Any) -> bool:
    if isinstance(value, bool):
        return value
    if isinstance(value, str):
        return value.strip().lower() == 'true'
    return bool(value)


def to_float(value: Any) -> float:
    if value is None:
        raise ValueError('missing numeric value')
    if isinstance(value, (int, float)):
        return float(value)
    return float(str(value).strip())


def to_int(value: Any) -> int:
    if value is None:
        raise ValueError('missing integer value')
    if isinstance(value, int):
        return value
    if isinstance(value, float):
        return int(value)
    return int(float(str(value).strip()))


def read_csv(path: Path) -> List[Dict[str, str]]:
    with path.open(newline='', encoding='utf-8') as f:
        return list(csv.DictReader(f))


def normalize_aliases(value: Any) -> List[str]:
    if value is None:
        return []
    if isinstance(value, list):
        return [str(v) for v in value]
    if isinstance(value, str):
        stripped = value.strip()
        if not stripped:
            return []
        # Some tasks encode aliases as JSON strings; fall back to separators.
        try:
            parsed = json.loads(stripped)
            if isinstance(parsed, list):
                return [str(v) for v in parsed]
        except json.JSONDecodeError:
            pass
        for sep in ['|', ';', ',']:
            if sep in stripped:
                return [part.strip() for part in stripped.split(sep) if part.strip()]
        return [stripped]
    return [str(value)]


def iter_therapy_entries(obj: Any) -> Iterable[Dict[str, Any]]:
    """Yield therapy-like dicts from a catalog that may be nested as list/dict."""
    if isinstance(obj, list):
        for item in obj:
            yield from iter_therapy_entries(item)
    elif isinstance(obj, dict):
        if 'therapy_code' in obj:
            yield obj
        else:
            for value in obj.values():
                yield from iter_therapy_entries(value)


def choose_patient_column(rows: List[Dict[str, str]]) -> str:
    if not rows:
        raise ValueError('patient_overrides.csv has no rows')
    columns = list(rows[0].keys())
    preferred = ['active_patients', 'patient_count', 'patients', 'active_patient_count', 'num_patients']
    for col in preferred:
        if col in columns:
            return col
    for col in columns:
        lowered = col.lower()
        if 'patient' in lowered and col not in {'therapy_code'}:
            return col
    raise ValueError(f'Could not identify patient count column in {columns}')


def money(value: float) -> float:
    return round(float(value), 2)


def main() -> None:
    catalog = json.loads(CATALOG_PATH.read_text(encoding='utf-8'))
    all_therapies = list(iter_therapy_entries(catalog))
    in_scope = [t for t in all_therapies if as_bool(t.get('include_in_review'))]
    in_scope_codes = {str(t['therapy_code']) for t in in_scope}

    bag_rows = read_csv(BAG_PATH)
    bag_cost_by_size = {str(to_int(row['bag_size_ml'])): to_float(row['bag_supply_cost_usd']) for row in bag_rows}

    payment_rows = read_csv(PAYMENT_PATH)
    payment_by_label = {
        str(row['therapy_label']): to_float(row['payment_per_delivery_per_patient_usd'])
        for row in payment_rows
    }

    override_rows = read_csv(OVERRIDES_PATH)
    patient_col = choose_patient_column(override_rows)
    best_approved_by_code: Dict[str, Dict[str, str]] = {}
    for row in override_rows:
        code = str(row.get('therapy_code', '')).strip()
        if row.get('status') != 'approved' or code not in in_scope_codes:
            continue
        revision = to_int(row.get('revision', 0))
        current = best_approved_by_code.get(code)
        if current is None or revision > to_int(current.get('revision', 0)):
            best_approved_by_code[code] = row

    therapies_out: List[Dict[str, Any]] = []
    for therapy in sorted(in_scope, key=lambda t: str(t['therapy_code'])):
        code = str(therapy['therapy_code'])
        name = str(therapy['therapy_name'])
        aliases = normalize_aliases(therapy.get('aliases'))
        labels = [name] + aliases
        matching_labels = [label for label in labels if label in payment_by_label]
        if not matching_labels:
            raise ValueError(f'No delivery payment found for in-scope therapy {code} using labels {labels}')
        # If more than one catalog label maps to a payment row, require consistent value.
        matched_payments = {payment_by_label[label] for label in matching_labels}
        if len(matched_payments) != 1:
            raise ValueError(f'Conflicting delivery payments for {code}: {matching_labels}')
        payment = matched_payments.pop()

        patient_row = best_approved_by_code.get(code)
        if patient_row is None:
            raise ValueError(f'No approved patient override found for in-scope therapy {code}')
        active_patients = to_int(patient_row[patient_col])

        bag_size = to_int(therapy['bag_size_ml'])
        bag_supply_cost = bag_cost_by_size.get(str(bag_size))
        if bag_supply_cost is None:
            raise ValueError(f'No bag supply cost found for bag_size_ml={bag_size} therapy={code}')

        drug_cost_per_1000 = to_float(therapy['drug_cost_per_1000_mg_usd'])
        dose = to_float(therapy['dose_mg_per_day'])

        def calc(days_per_delivery: int, deliveries_per_year: int) -> Dict[str, float]:
            annual_drug_cost = drug_cost_per_1000 * active_patients * dose * days_per_delivery * deliveries_per_year / 1000.0
            annual_supply_cost = bag_supply_cost * active_patients * deliveries_per_year
            annual_revenue = payment * active_patients * deliveries_per_year
            annual_margin = annual_revenue - annual_drug_cost - annual_supply_cost
            return {
                'annual_drug_cost': money(annual_drug_cost),
                'annual_supply_cost': money(annual_supply_cost),
                'annual_revenue': money(annual_revenue),
                'annual_margin': money(annual_margin),
            }

        seven = calc(days_per_delivery=7, deliveries_per_year=52)
        fourteen = calc(days_per_delivery=14, deliveries_per_year=26)
        margin_diff = money(fourteen['annual_margin'] - seven['annual_margin'])

        therapies_out.append({
            'therapy_code': code,
            'therapy_name': name,
            'active_patients': active_patients,
            'payment_per_delivery_per_patient_usd': money(payment),
            'bag_supply_cost_usd': money(bag_supply_cost),
            'annual_drug_cost_7_day_usd': seven['annual_drug_cost'],
            'annual_supply_cost_7_day_usd': seven['annual_supply_cost'],
            'annual_revenue_7_day_usd': seven['annual_revenue'],
            'annual_margin_7_day_usd': seven['annual_margin'],
            'annual_drug_cost_14_day_usd': fourteen['annual_drug_cost'],
            'annual_supply_cost_14_day_usd': fourteen['annual_supply_cost'],
            'annual_revenue_14_day_usd': fourteen['annual_revenue'],
            'annual_margin_14_day_usd': fourteen['annual_margin'],
            'annual_margin_difference_14_minus_7_usd': margin_diff,
        })

    total_7 = money(sum(t['annual_margin_7_day_usd'] for t in therapies_out))
    total_14 = money(sum(t['annual_margin_14_day_usd'] for t in therapies_out))
    total_diff = money(sum(t['annual_margin_difference_14_minus_7_usd'] for t in therapies_out))
    abs_total_diff = money(abs(total_diff))
    decision = 'move_to_14_day' if abs_total_diff < 15000 else 'keep_7_day'
    justification = (
        f'Absolute annual margin difference is ${abs_total_diff:.2f}, '
        f"which is {'below' if abs_total_diff < 15000 else 'at or above'} the $15000 threshold; decision is {decision}."
    )

    output = {
        'therapies': therapies_out,
        'total_annual_margin_7_day_usd': total_7,
        'total_annual_margin_14_day_usd': total_14,
        'total_annual_margin_difference_14_minus_7_usd': total_diff,
        'absolute_total_margin_difference_usd': abs_total_diff,
        'decision': decision,
        'justification': justification,
    }

    with OUTPUT_JSON_PATH.open('w', encoding='utf-8') as f:
        json.dump(output, f, indent=2)
        f.write('\n')

    summary_lines = [
        f'Total 7-day margin (USD): {total_7:.2f}',
        f'Total 14-day margin (USD): {total_14:.2f}',
        f'Absolute difference (USD): {abs_total_diff:.2f}',
        f'Final decision: {decision}',
        justification,
    ]
    OUTPUT_MD_PATH.write_text('\n'.join(summary_lines) + '\n', encoding='utf-8')


if __name__ == '__main__':
    main()
